// 2. Code: Validate Event — validate lead ID and idempotency/correlation fields
const item = $input.first().json;
let payload = {};

if (item.content) {
  try {
    payload = typeof item.content === "string" ? JSON.parse(item.content) : item.content;
  } catch (err) {
    payload = {};
  }
} else {
  payload = item;
}

if (payload && payload.type === "Buffer" && Array.isArray(payload.data)) {
  try {
    payload = JSON.parse(Buffer.from(payload.data).toString("utf8"));
  } catch (e) {}
}

const eventData = payload.data || payload;
const leadId = eventData.leadId || payload.leadId || null;
const workflowRunId = eventData.workflowRunId || payload.workflowRunId || null;

if (!leadId) {
  throw new Error("Validation error: Missing leadId in RabbitMQ payload");
}

if (!workflowRunId) {
  throw new Error("Validation error: Missing workflowRunId in RabbitMQ payload");
}

return [{
  json: {
    leadId,
    workflowRunId,
    eventData,
    rawEvent: payload
  }
}];

// 7. Code: Aggregate Features — validate internal read results, apply explicit degraded fallback policy, and forward raw context to backend policy evaluator
const eventMeta = $('Code: Validate Event').first().json;
const leadRes = $('HTTP Request: Get Lead').first().json;
const qualRes = $('HTTP Request: Get Latest Qualification').first().json;
const enrichRes = $('HTTP Request: Get Latest Enrichment').first().json;
const contextRes = $('HTTP Request: Get Interactions').first().json;

const leadId = eventMeta.leadId;
const workflowRunId = eventMeta.workflowRunId;
const eventData = eventMeta.eventData || {};
const eventScoringContext = eventData.scoringContext || {};

function extractHttpError(res) {
  if (!res || typeof res !== "object") return null;
  const statusCode =
    res.statusCode ||
    res.status ||
    (res.error && (res.error.statusCode || res.error.status || res.error.httpCode)) ||
    null;
  const hasError =
    Boolean(res.error) ||
    (typeof statusCode === "number" && statusCode >= 400);
  if (!hasError) return null;
  const message =
    (typeof res.error === "object" && res.error !== null && res.error.message) ||
    (typeof res.message === "string" && res.message) ||
    (typeof res.error === "string" && res.error) ||
    ("HTTP error " + (statusCode || "unknown"));
  return { statusCode: typeof statusCode === "number" ? statusCode : 500, message };
}

const readNodes = [
  { name: "HTTP Request: Get Lead", err: extractHttpError(leadRes) },
  { name: "HTTP Request: Get Latest Qualification", err: extractHttpError(qualRes) },
  { name: "HTTP Request: Get Latest Enrichment", err: extractHttpError(enrichRes) },
  { name: "HTTP Request: Get Interactions", err: extractHttpError(contextRes) }
];

// Fail immediately on auth errors (401/403) across any internal read node
for (const node of readNodes) {
  if (node.err && (node.err.statusCode === 401 || node.err.statusCode === 403)) {
    throw new Error("Fatal authentication/authorization error (" + node.err.statusCode + ") in " + node.name + ": " + node.err.message);
  }
}

let degradedRead = false;
const sources = {
  lead: "backend_http",
  qualification: "backend_http",
  enrichment: "backend_http",
  interactions: "backend_http"
};
const readErrors = [];

// 1. Lead resolution (fail on 404; require validated event snapshot on transient read failure)
const leadErr = readNodes[0].err;
if (leadErr && leadErr.statusCode === 404) {
  throw new Error("Lead not found (404) in HTTP Request: Get Lead: " + leadErr.message);
}

let lead = null;
if (!leadErr && leadRes && leadRes.id === leadId) {
  lead = leadRes;
} else {
  const fallbackLead = eventData.leadData || eventScoringContext.lead || eventData.lead || null;
  const hasValidFallbackLead =
    fallbackLead &&
    typeof fallbackLead === "object" &&
    (!fallbackLead.id || fallbackLead.id === leadId) &&
    Boolean(
      fallbackLead.email ||
      fallbackLead.companyName ||
      fallbackLead.jobTitle ||
      typeof fallbackLead.companySize === "number"
    );
  if (!hasValidFallbackLead) {
    throw new Error(
      "HTTP Request: Get Lead failed (" +
        (leadErr ? leadErr.message : "missing or mismatched lead id") +
        ") and no valid leadData snapshot is available in event payload"
    );
  }
  lead = { ...fallbackLead, id: fallbackLead.id || leadId };
  sources.lead = "event_fallback";
  degradedRead = true;
  readErrors.push({
    node: "HTTP Request: Get Lead",
    statusCode: leadErr ? leadErr.statusCode : null,
    message: leadErr ? leadErr.message : "Missing or mismatched lead id in HTTP response",
    fallbackUsed: "eventData.leadData"
  });
}

// 2. Qualification resolution
const qualErr = readNodes[1].err;
let qual = null;
if (!qualErr) {
  qual = qualRes && qualRes.status ? qualRes : null;
} else {
  const hasQualFallbackKey =
    "qualificationData" in eventData ||
    "qualification" in eventScoringContext ||
    "qualification" in eventData;
  if (!hasQualFallbackKey) {
    throw new Error(
      "HTTP Request: Get Latest Qualification failed (" +
        qualErr.message +
        ") and no qualificationData snapshot is available in event payload"
    );
  }
  qual =
    eventData.qualificationData ??
    eventScoringContext.qualification ??
    eventData.qualification ??
    null;
  sources.qualification = "event_fallback";
  degradedRead = true;
  readErrors.push({
    node: "HTTP Request: Get Latest Qualification",
    statusCode: qualErr.statusCode,
    message: qualErr.message,
    fallbackUsed: "eventData.qualificationData"
  });
}

// 3. Enrichment resolution
const enrichErr = readNodes[2].err;
let enrich = null;
if (!enrichErr) {
  enrich = enrichRes && (enrichRes.id || enrichRes.status) ? enrichRes : null;
} else {
  const hasEnrichFallbackKey =
    "enrichmentData" in eventData ||
    "enrichment" in eventScoringContext ||
    "enrichment" in eventData;
  if (!hasEnrichFallbackKey) {
    throw new Error(
      "HTTP Request: Get Latest Enrichment failed (" +
        enrichErr.message +
        ") and no enrichmentData snapshot is available in event payload"
    );
  }
  enrich =
    eventData.enrichmentData ??
    eventScoringContext.enrichment ??
    eventData.enrichment ??
    null;
  sources.enrichment = "event_fallback";
  degradedRead = true;
  readErrors.push({
    node: "HTTP Request: Get Latest Enrichment",
    statusCode: enrichErr.statusCode,
    message: enrichErr.message,
    fallbackUsed: "eventData.enrichmentData"
  });
}

// 4. Interactions resolution
const contextErr = readNodes[3].err;
let interactions = [];
if (!contextErr && contextRes && Array.isArray(contextRes.interactions)) {
  interactions = contextRes.interactions;
} else {
  const fallbackInteractions =
    Array.isArray(eventData.interactions)
      ? eventData.interactions
      : Array.isArray(eventScoringContext.interactions)
        ? eventScoringContext.interactions
        : null;
  if (!fallbackInteractions) {
    throw new Error(
      "HTTP Request: Get Interactions failed (" +
        (contextErr ? contextErr.message : "missing interactions array") +
        ") and no valid interactions snapshot is available in event payload"
    );
  }
  interactions = fallbackInteractions;
  sources.interactions = "event_fallback";
  degradedRead = true;
  readErrors.push({
    node: "HTTP Request: Get Interactions",
    statusCode: contextErr ? contextErr.statusCode : null,
    message: contextErr ? contextErr.message : "Missing interactions array in HTTP response",
    fallbackUsed: "eventData.interactions"
  });
}

const contextAudit = {
  degradedRead,
  sources,
  readErrors
};

return [{
  json: {
    leadId,
    workflowRunId,
    lead,
    qual,
    enrich,
    interactions,
    contextAudit
  }
}];

// 9. Code: Validate Canonical Score — validate response shape, score boundaries, label and policy version
const response = $input.first().json;
const prep = $('Code: Aggregate Features').first().json;

const leadId = prep.leadId;
const workflowRunId = prep.workflowRunId;

if (typeof response.score !== "number" || isNaN(response.score) || response.score < 0 || response.score > 100) {
  throw new Error("Invalid score received from scoring policy: " + response.score);
}

if (!["HOT", "WARM", "COLD"].includes(response.label)) {
  throw new Error("Invalid score label received from scoring policy: " + response.label);
}

if (!response.policyVersion) {
  throw new Error("Missing policyVersion in scoring policy response");
}

const resolvedModelProvider =
  (response.modelInfo && response.modelInfo.provider) || "crm-scoring-policy";
const resolvedModelName =
  (response.modelInfo && response.modelInfo.model) || "deterministic-scoring-v1";
const resolvedModelVersion =
  (response.modelInfo && (response.modelInfo.modelVersion || response.modelInfo.version)) ||
  response.policyVersion;

const scoringFeatures = {
  ...(response.scoringFeatures || {}),
  ...(prep.contextAudit ? { contextAudit: prep.contextAudit } : {})
};

return [{
  json: {
    leadId,
    workflowRunId,
    status: "SUCCESS",
    score: response.score,
    label: response.label,
    policyVersion: response.policyVersion,
    modelProvider: resolvedModelProvider,
    modelName: resolvedModelName,
    modelVersion: resolvedModelVersion,
    reason: response.reason || ("[Canonical Policy - " + response.label + " " + response.score + "/100]"),
    scoringFeatures,
    inputSnapshot: {
      leadId,
      workflowRunId,
      contextAudit: prep.contextAudit || null
    },
    outputSnapshot: {
      score: response.score,
      label: response.label,
      policyVersion: response.policyVersion,
      breakdown: response.breakdown || null
    },
    modelInfo: {
      provider: resolvedModelProvider,
      model: resolvedModelName,
      modelVersion: resolvedModelVersion,
      version: resolvedModelVersion
    },
    evaluatedAt: new Date().toISOString()
  }
}];

